/**
 * One-time generator: fetches Roboto-Regular.ttf (Greek-capable) from a stable
 * mirror and writes a jsPDF-compatible JS module that auto-registers the font
 * for any new jsPDF instance.
 *
 * Run with:  node scripts/generate-pdf-fonts.mjs
 *
 * The generated file is committed to the repo so production builds never
 * touch the network. Re-run only if you want to refresh the font.
 */

import { mkdir, writeFile } from 'node:fs/promises';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const FONT_URL = 'https://cdn.jsdelivr.net/gh/googlefonts/roboto@main/src/hinted/Roboto-Regular.ttf';
const OUT_DIR = path.join(__dirname, '..', 'src', 'assets', 'fonts');
const OUT_FILE = path.join(OUT_DIR, 'Roboto-Regular-normal.js');

async function fetchTtf(url) {
  const resp = await fetch(url);
  if (!resp.ok) throw new Error(`Font fetch failed (${resp.status}): ${url}`);
  return Buffer.from(await resp.arrayBuffer());
}

async function main() {
  console.log('Fetching Roboto-Regular.ttf from', FONT_URL);
  let ttf;
  try {
    ttf = await fetchTtf(FONT_URL);
  } catch (err) {
    // Fall back to a second mirror if the first one is unreachable.
    const fallback = 'https://raw.githubusercontent.com/googlefonts/roboto/main/src/hinted/Roboto-Regular.ttf';
    console.warn('Primary fetch failed:', err.message, '\nTrying fallback:', fallback);
    ttf = await fetchTtf(fallback);
  }
  console.log(`Got ${ttf.byteLength} bytes`);

  const base64 = ttf.toString('base64');

  // jsPDF v4 API: register the font once via the events.push hook so it's
  // available on every new jsPDF instance.
  const js = `/* eslint-disable */
/**
 * Auto-generated by scripts/generate-pdf-fonts.mjs — do not edit.
 *
 * Registers Roboto-Regular with jsPDF so PDFs render Greek characters
 * correctly (the default Helvetica is Latin-only).
 */
import { jsPDF } from 'jspdf';

const robotoRegularBase64 = '${base64}';

jsPDF.API.events.push(['addFonts', function () {
  this.addFileToVFS('Roboto-Regular-normal.ttf', robotoRegularBase64);
  this.addFont('Roboto-Regular-normal.ttf', 'Roboto', 'normal');
}]);
`;

  await mkdir(OUT_DIR, { recursive: true });
  await writeFile(OUT_FILE, js, 'utf8');
  console.log('Wrote', OUT_FILE, `(${(js.length / 1024).toFixed(1)} KB)`);
}

main().catch(err => {
  console.error('Font generation failed:', err);
  process.exit(1);
});
